  FURIN: { headline: "A/G — Umiarkowany", impact: "Zbalansowany stosunek proBDNF do mBDNF; standardowy profil populacyjny.", toneCtx: { heading: "rs4702", genotype: "A/G", tone: "neutral" }, variants: [{ headline: "A/G — Umiarkowany", text: "Zbalansowany stosunek proBDNF do mBDNF; standardowy profil populacyjny.", heading: "rs4702", genotype: "A/G", tone: "neutral" }], byTopic: { asd: { variants: [{ headline: "A/G — Umiarkowany", text: "Rola biologiczna genu/białka: Proteaza serynowa, która w mózgu odpowiada za enzymatyczne cięcie prekursora neurotrofiny (proBDNF) do jej dojrzałej, funkcjonalnej formy (mBDNF). Podczas gdy proBDNF promuje apoptozę i usuwanie synaps (poprzez receptor p75NTR), mBDNF stymuluje wzrost neuronów i LTP (poprzez receptor TrkB). Furin decyduje o tym krytycznym dla mózgu balansie.", heading: "rs4702", genotype: "A/G", tone: "neutral" }] } } },
  GABBR2: { headline: "G/G — Wysoka sprawność hamowania wolnego", impact: "Stabilna kontrola pobudliwości sieciowej. Doskonała zdolność do relaksacji układu nerwowego, prawidłowa jakość snu głębokiego (wolnofalowego), wysoka odporność na lęk napadowy.", toneCtx: { heading: "rs1435252", genotype: "G/G", tone: "positive" }, variants: [{ headline: "G/G — Wysoka sprawność hamowania wolnego", text: "Stabilna kontrola pobudliwości sieciowej. Doskonała zdolność do relaksacji układu nerwowego, prawidłowa jakość snu głębokiego (wolnofalowego), wysoka odporność na lęk napadowy.", heading: "rs1435252", genotype: "G/G", tone: "positive" }], byTopic: { asd: { variants: [{ headline: "G/G — Wysoka sprawność hamowania wolnego", text: "Rola biologiczna genu/białka: Koduje podjednostkę heterodimerycznego receptora GABA-B. W przeciwieństwie do jonotropowego GABA-A, receptor GABA-B działa wolniej, lecz długofalowo – poprzez białka G (Gi/o) i aktywację kanałów potasowych GIRK. Wywołuje głęboką hiperpolaryzację, stabilizując błonę postsynaptyczną i zapobiegając uogólnionym wyładowaniom drgawkowym.", heading: "rs1435252", genotype: "G/G", tone: "positive" }] }, mdd: { variants: [{ headline: "G/G — Wysoka sprawność hamowania wolnego", text: "Stabilna kontrola pobudliwości sieciowej. Doskonała zdolność do relaksacji układu nerwowego, prawidłowa jakość snu głębokiego (wolnofalowego), wysoka odporność na lęk napadowy.", heading: "rs1435252", genotype: "G/G", tone: "positive" }] } } },
