  "HLA-B": { headline: "A/A — Zbalansowany pruning", impact: "Prawidłowa, selektywna eliminacja zbędnych lub słabych połączeń synaptycznych w dzieciństwie. Stabilna tolerancja immunologiczna, optymalna gęstość sieci neuronowych.", toneCtx: { heading: "rs3135388", genotype: "A/A", tone: "positive" }, variants: [{ headline: "A/A — Zbalansowany pruning", text: "Prawidłowa, selektywna eliminacja zbędnych lub słabych połączeń synaptycznych w dzieciństwie. Stabilna tolerancja immunologiczna, optymalna gęstość sieci neuronowych.", heading: "rs3135388", genotype: "A/A", tone: "positive" }], byTopic: { asd: { variants: [{ headline: "A/A — Zbalansowany pruning", text: "Prawidłowa, selektywna eliminacja zbędnych lub słabych połączeń synaptycznych w dzieciństwie. Stabilna tolerancja immunologiczna, optymalna gęstość sieci neuronowych.", heading: "rs3135388", genotype: "A/A", tone: "positive" }] }, neurodev: { variants: [{ headline: "A/A — Zbalansowany pruning", text: "Rola biologiczna genu/białka: Prezentuje peptydy pochodzenia wewnątrzkomórkowego limfocytom T cytotoksycznym (CD8+). W ośrodkowym układzie nerwowym cząsteczki MHC klasy I pełnią kluczową rolę nieimmunologiczną: regulują proces \"pruningu\" (synaptycznego przycinania) realizowanego przez mikroglej w trakcie rozwoju kory mózgowej.", heading: "rs3135388", genotype: "A/A", tone: "positive" }] } } },
