  KCNN2: { headline: "T/T — Silne hamowanie", impact: "Błyskawiczna repolaryzacja i wysoka ochrona przed ekscytotoksycznością. Może podnosić próg aktywacji kognitywnej (potrzeba silniejszych bodźców środowiskowych do indukcji procesów zapamiętywania).", toneCtx: { heading: "rs6480535", genotype: "T/T", tone: "positive" }, variants: [{ headline: "T/T — Silne hamowanie", text: "Błyskawiczna repolaryzacja i wysoka ochrona przed ekscytotoksycznością. Może podnosić próg aktywacji kognitywnej (potrzeba silniejszych bodźców środowiskowych do indukcji procesów zapamiętywania).", heading: "rs6480535", genotype: "T/T", tone: "positive" }], byTopic: { asd: { variants: [{ headline: "T/T — Silne hamowanie", text: "Rola biologiczna genu/białka: Koduje kanał potasowy SK2, który otwiera się w odpowiedzi na wzrost stężenia intracelularnego wapnia. Generuje prąd hiperpolaryzacji pościegłowej (AHP), pełniąc funkcję \"hamulca bezpieczeństwa\" – ogranicza częstotliwość wyładowań neuronu i chroni go przed przestymulowaniem. Kluczowy dla plastyczności synaptycznej w hipokampie.", heading: "rs6480535", genotype: "T/T", tone: "positive" }] }, "cognition-aging": { variants: [{ headline: "T/T — Silne hamowanie", text: "Rola biologiczna genu/białka: Koduje kanał potasowy SK2, który otwiera się w odpowiedzi na wzrost stężenia intracelularnego wapnia. Generuje prąd hiperpolaryzacji pościegłowej (AHP), pełniąc funkcję \"hamulca bezpieczeństwa\" – ogranicza częstotliwość wyładowań neuronu i chroni go przed przestymulowaniem. Kluczowy dla plastyczności synaptycznej w hipokampie.", heading: "rs6480535", genotype: "T/T", tone: "positive" }] } } },
  KCNQ3: { headline: "C/T — Subtelne wahania ekspresji", impact: "Niewielkie różnice w podatności na zmęczenie neuroelektryczne; sporadyczne bóle głowy typu migrenowego przy przeciążeniach bodźcami.", toneCtx: { heading: "rs13271739", genotype: "C/T", tone: "neutral" }, variants: [{ headline: "C/T — Subtelne wahania ekspresji", text: "Niewielkie różnice w podatności na zmęczenie neuroelektryczne; sporadyczne bóle głowy typu migrenowego przy przeciążeniach bodźcami.", heading: "rs13271739", genotype: "C/T", tone: "neutral" }], byTopic: { appearance: { variants: [{ headline: "C/T — Subtelne wahania ekspresji", text: "Rola biologiczna genu/białka: Wspólnie z podjednostką KCNQ2 tworzy funkcjonalny kanał potasowy generujący tzw. prąd M. Jest to prąd potasowy aktywowany powolną depolaryzacją, który nie ulega inaktywacji. Pełni rolę nadrzędnego stabilizatora potencjału spoczynkowego neuronu – zapobiega generowaniu powtarzalnych, seryjnych wyładowań iglicowych (bursting).", heading: "rs13271739", genotype: "C/T", tone: "neutral" }] } } },
  KCNQ4: { headline: "T/A — Częściowo obniżone IK pod stresem", impact: "~1,5× ryzyko NIHL przy ekspozycji na hałas", toneCtx: { heading: "rs4660470 (NIHL — utrata słuchu indukowana hałasem)", genotype: "T/A" }, variants: [{ headline: "T/A — Częściowo obniżone IK pod stresem", text: "~1,5× ryzyko NIHL przy ekspozycji na hałas", heading: "rs4660470 (NIHL — utrata słuchu indukowana hałasem)", genotype: "T/A" }, { headline: "C/T — Łagodne obniżenie stabilności błony", text: "Umiarkowanie zwiększona podatność na NIHL", heading: "rs4660468 (NIHL — haplotyp)", genotype: "C/T" }, { headline: "G/G — Prawidłowy kanał", text: "Norma słuchu", heading: "rs28937588 (p.Gly285Ser — DFNA2A patogenny)", genotype: "G/G" }, { headline: "G/G — Trp276/Trp276 — prawidłowy Kv7.4", text: "Norma słuchu; brak mutacji patogennej DFNA2A", heading: "rs80358277 (c.827G>C p.Trp276Ser — DFNA2A)", genotype: "G/G" }], byTopic: { psychopharm: { variants: [{ headline: "T/A — Częściowo obniżone IK pod stresem", text: "Farmakologia: Unikać salicylanów i antybiotyków ototoksycznych (aminoglikozydy) u nosicieli alleli ryzyka — po konsultacji lekarskiej.", heading: "rs4660470 (NIHL — utrata słuchu indukowana hałasem)", genotype: "T/A" }] }, sport: { variants: [{ headline: "T/A — Częściowo obniżone IK pod stresem", text: "Styl życia: Ograniczyć alkohol u alleli ryzyka (modulacja VTA); trening aerobowy dla ochrony naczyniowej Kv7.4.", heading: "rs4660470 (NIHL — utrata słuchu indukowana hałasem)", genotype: "T/A" }] }, substances: { variants: [{ headline: "T/A — Częściowo obniżone IK pod stresem", text: "Styl życia: Ograniczyć alkohol u alleli ryzyka (modulacja VTA); trening aerobowy dla ochrony naczyniowej Kv7.4.", heading: "rs4660470 (NIHL — utrata słuchu indukowana hałasem)", genotype: "T/A" }] } } },
