  KMT2D: { headline: "A/A — Prawidłowa metylacja histonów", impact: "Stabilna, skoordynowana transkrypcja zależna od stanu euchromatyny. Harmonijny rozwój struktur somatycznych oraz prawidłowy przebieg neurogenezy dorosłej w hipokampie.", toneCtx: { heading: "rs772057441", genotype: "A/A", tone: "positive" }, variants: [{ headline: "A/A — Prawidłowa metylacja histonów", text: "Stabilna, skoordynowana transkrypcja zależna od stanu euchromatyny. Harmonijny rozwój struktur somatycznych oraz prawidłowy przebieg neurogenezy dorosłej w hipokampie.", heading: "rs772057441", genotype: "A/A", tone: "positive" }], byTopic: { "cognition-aging": { variants: [{ headline: "A/A — Prawidłowa metylacja histonów", text: "Stabilna, skoordynowana transkrypcja zależna od stanu euchromatyny. Harmonijny rozwój struktur somatycznych oraz prawidłowy przebieg neurogenezy dorosłej w hipokampie.", heading: "rs772057441", genotype: "A/A", tone: "positive" }] }, folate: { variants: [{ headline: "A/A — Prawidłowa metylacja histonów", text: "Rola biologiczna genu/białka: KMT2D odpowiada za mono-, di- i trimetylację lizyny 4 w histonie H3 (H3K4me1/2/3). Modyfikacja ta stanowi nadrzędny sygnał epigenetyczny do rozluźnienia struktury chromatyny (przejście w euchromatynę), co umożliwia aktywację transkrypcji genów kluczowych dla rozwoju twarzoczaszki, narządów wewnętrznych oraz neurogenezy w hipokampie.", heading: "rs772057441", genotype: "A/A", tone: "positive" }] }, neurodev: { variants: [{ headline: "A/A — Prawidłowa metylacja histonów", text: "Rola biologiczna genu/białka: KMT2D odpowiada za mono-, di- i trimetylację lizyny 4 w histonie H3 (H3K4me1/2/3). Modyfikacja ta stanowi nadrzędny sygnał epigenetyczny do rozluźnienia struktury chromatyny (przejście w euchromatynę), co umożliwia aktywację transkrypcji genów kluczowych dla rozwoju twarzoczaszki, narządów wewnętrznych oraz neurogenezy w hipokampie.", heading: "rs772057441", genotype: "A/A", tone: "positive" }] } } },
  LCT: { headline: "C/C — Pierwotna Hipolaktazja Dorosłych (LNP)", impact: "Charakteryzuje się najniższą lub bliską zeru aktywnością enzymu laktazy u dorosłych. W populacjach europejskich zwiastuje objawową nietolerancję laktozy, a także koreluje z niekorzystnym profilem lipidowym i podwyższonym wskaźnikiem ApoB100.", toneCtx: { heading: "rs4988235 (persystencja laktazy)", genotype: "C/C (G/G komplementarnie)" }, variants: [{ headline: "C/C — Pierwotna Hipolaktazja Dorosłych (LNP)", text: "Charakteryzuje się najniższą lub bliską zeru aktywnością enzymu laktazy u dorosłych. W populacjach europejskich zwiastuje objawową nietolerancję laktozy, a także koreluje z niekorzystnym profilem lipidowym i podwyższonym wskaźnikiem ApoB100.", heading: "rs4988235 (persystencja laktazy)", genotype: "C/C (G/G komplementarnie)" }, { headline: "C/C — Brak allelu persystencji (tag)", text: "Skorelowany z hipolaktazją dorosłych w LD z rs4988235 C; typowa nietolerancja laktozy przy C/C rs4988235", heading: "rs182549 (c.220+1G>A w MCM6 — tag persystencji laktazy)", genotype: "C/C" }], byTopic: { nutrition: { variants: [{ headline: "C/C — Pierwotna Hipolaktazja Dorosłych (LNP)", text: "Charakteryzuje się najniższą lub bliską zeru aktywnością enzymu laktazy u dorosłych. W populacjach europejskich zwiastuje objawową nietolerancję laktozy, a także koreluje z niekorzystnym profilem lipidowym i podwyższonym wskaźnikiem ApoB100.", heading: "rs4988235 (persystencja laktazy)", genotype: "C/C (G/G komplementarnie)" }, { headline: "C/C — Brak allelu persystencji (tag)", text: "Skorelowany z hipolaktazją dorosłych w LD z rs4988235 C; typowa nietolerancja laktozy przy C/C rs4988235", heading: "rs182549 (c.220+1G>A w MCM6 — tag persystencji laktazy)", genotype: "C/C" }] }, sport: { variants: [{ headline: "C/C — Pierwotna Hipolaktazja Dorosłych (LNP)", text: "Sport i Odżywki: Badania nie potwierdzają, by wariant C/T miał znaczenie w budowaniu tkanki mięśniowej czy tolerancji wysiłku. Mając jednak genotyp C/C, sportowiec nie powinien spożywać koncentratu serwatki (WPC) obfitującego w laktozę; zaleca się bezwzględne korzystanie z czystych izolatów białkowych (WPI) lub wegańskich odpowiedników grochowo-ryżowych w celu uniknięcia retencji wody.", heading: "rs4988235 (persystencja laktazy)", genotype: "C/C (G/G komplementarnie)" }] } } },
