  NSUN2: { headline: "C/C — Pełna ochrona i stabilność RNA", impact: "Prawidłowa, optymalna synteza białek w komórkach progenitorowych mózgu. Prawidłowy wzrost somatyczny i neurobiologiczny.", toneCtx: { heading: "rs11553556", genotype: "C/C", tone: "positive" }, variants: [{ headline: "C/C — Pełna ochrona i stabilność RNA", text: "Prawidłowa, optymalna synteza białek w komórkach progenitorowych mózgu. Prawidłowy wzrost somatyczny i neurobiologiczny.", heading: "rs11553556", genotype: "C/C", tone: "positive" }], byTopic: { folate: { variants: [{ headline: "C/C — Pełna ochrona i stabilność RNA", text: "Rola biologiczna genu/białka: NSUN2 odpowiada za metylację cytozyny do 5-metylocytozyny (m5C) w cząsteczkach tRNA, mRNA i niekodujących RNA. Metylacja ta chroni tRNA przed pękaniem i degradacją pod wpływem stresu komórkowego. Jest to absolutnie krytyczne dla precyzji i tempa translacji białek strukturalnych rozwijającego się mózgu.", heading: "rs11553556", genotype: "C/C", tone: "positive" }] } } },
