  OXTR: { headline: "A/G — Heterozygota (Pośrednia)", impact: "Fenotyp Modulowany: Profil wykazujący pośrednie wartości neurofizjologiczne. W wielu analizach medycznych wystarczy jednak obecność jednej kopii allelu A, by wykazać osłabione mechanizmy buforowania wsparcia. Jednostki te dysponują umiarkowanymi wynikami empatycznymi w populacji ogólnej bez drastycznych wahań.", toneCtx: { heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }, variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Fenotyp Modulowany: Profil wykazujący pośrednie wartości neurofizjologiczne. W wielu analizach medycznych wystarczy jednak obecność jednej kopii allelu A, by wykazać osłabione mechanizmy buforowania wsparcia. Jednostki te dysponują umiarkowanymi wynikami empatycznymi w populacji ogólnej bez drastycznych wahań.", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }], byTopic: { asd: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Kofaktory – Magnez (Mg2+) i Witamina D: Jony magnezu są absolutnie konieczne, by receptor OXT zachował konformację umożliwiającą przyłączanie hormonu i skutecznie hamował pobudliwość neuronów (hiperpolaryzacja). Dodatkowo podaż witaminy D bezpośrednio aktywuje transkrypcję z obszaru OXTR w jądrze, potęgując pulę receptorów i hormonu w ciele migdałowatym.", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] }, folate: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Styl życia: Aktywacja rzutów oksytocyny może być samodzielnie wspomagana bez chemii. Somatyczne wyzwalanie układu aferentnego przy pomocy powięziowego masażu ucisku, regularnej jogi, wspólnego śpiewu i kontaktów z psami skutecznie podnosi podwzgórzową stymulację wolnego OXT u pacjentów.", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] }, psychopharm: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Rewolucja na osi Mikrobiom-Mózg: Niewątpliwym sukcesem neurobiologicznym jest wpływ specyficznego probiotyku Lactobacillus reuteri (ATCC-PTA-6475) wyizolowanego z mleka. Bakteria ta drastycznie stymuluje i uwalnia endogenną oksytocynę w mózgu omijając zjawiska odpornościowe komórek limfocytów. Wykorzystuje ona bezpośrednio połączenia wstępujące włókien nerwu błędnego u naczelnych, rewelacyjnie rewersując deficyty beh…", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] }, substances: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Używki a zdrowie wątroby: U układów pozbawionych barier (jak profil GG z wysoką korelacją prospołeczności), wykazano wysoce niezależny od ogólnego spożycia cukru pęd ku nawykowej konsumpcji mocnych form ujęć nagradzających (cukru i etanolu). Kobiety z homozygotą G/G są mocno dysponowane do ciężkich, uogólnionych schorzeń stłuszczeniowych wątroby z obu grup ryzyk (MASLD/ALD), co wymaga ostrego nadzoru prób wątrobowych…", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] } } },
  PDE4B: { headline: "T/T — Wariant prokognitywny", impact: "Wolniejsze rozkładanie cAMP. Wyższe stężenia drugiego przekaźnika stymulują plastyczność synaptyczną, podnosząc sprawność uczenia się, pamięci długotrwałej i elastyczności poznawczej.", toneCtx: { heading: "rs7412571", genotype: "T/T", tone: "positive" }, variants: [{ headline: "T/T — Wariant prokognitywny", text: "Wolniejsze rozkładanie cAMP. Wyższe stężenia drugiego przekaźnika stymulują plastyczność synaptyczną, podnosząc sprawność uczenia się, pamięci długotrwałej i elastyczności poznawczej.", heading: "rs7412571", genotype: "T/T", tone: "positive" }], byTopic: { asd: { variants: [{ headline: "T/T — Wariant prokognitywny", text: "Wolniejsze rozkładanie cAMP. Wyższe stężenia drugiego przekaźnika stymulują plastyczność synaptyczną, podnosząc sprawność uczenia się, pamięci długotrwałej i elastyczności poznawczej.", heading: "rs7412571", genotype: "T/T", tone: "positive" }] } } },
  POU3F2: { headline: "C/T — Wariant populacyjny", impact: "Standardowa plastyczność i strukturyzacja sieci korowych.", toneCtx: { heading: "rs1015362", genotype: "C/T", tone: "neutral" }, variants: [{ headline: "C/T — Wariant populacyjny", text: "Standardowa plastyczność i strukturyzacja sieci korowych.", heading: "rs1015362", genotype: "C/T", tone: "neutral" }], byTopic: { asd: { variants: [{ headline: "C/T — Wariant populacyjny", text: "Rola biologiczna genu/białka: Koduje nadrzędny czynnik transkrypcyjny (BRN2), który decyduje o tożsamości komórkowej, różnicowaniu i migracji neuronów projekcyjnych wyższych warstw kory nowej (warstwy II-IV). Kontroluje również prawidłowy rozwój jąder neurosekrecyjnych podwzgórza, regulując ekspresję setek genów odpowiedzialnych za formowanie synaps.", heading: "rs1015362", genotype: "C/T", tone: "neutral" }] }, folate: { variants: [{ headline: "C/T — Wariant populacyjny", text: "Rola biologiczna genu/białka: Koduje nadrzędny czynnik transkrypcyjny (BRN2), który decyduje o tożsamości komórkowej, różnicowaniu i migracji neuronów projekcyjnych wyższych warstw kory nowej (warstwy II-IV). Kontroluje również prawidłowy rozwój jąder neurosekrecyjnych podwzgórza, regulując ekspresję setek genów odpowiedzialnych za formowanie synaps.", heading: "rs1015362", genotype: "C/T", tone: "neutral" }] } } },
  PROZ: { headline: "T/T — Wysoki poziom Białka Z / Neuroprotekcja", impact: "Doskonała kontrola nad mikrokrążeniem mózgowym. Wysoka odporność naczyń na stany zapalne, optymalne dotlenienie tkanki nerwowej pod wpływem stresu.", toneCtx: { heading: "rs4253243", genotype: "T/T", tone: "positive" }, variants: [{ headline: "T/T — Wysoki poziom Białka Z / Neuroprotekcja", text: "Doskonała kontrola nad mikrokrążeniem mózgowym. Wysoka odporność naczyń na stany zapalne, optymalne dotlenienie tkanki nerwowej pod wpływem stresu.", heading: "rs4253243", genotype: "T/T", tone: "positive" }], byTopic: { cyp: { variants: [{ headline: "T/T — Wysoki poziom Białka Z / Neuroprotekcja", text: "Rola biologiczna genu/białka: Białko Z działa jako kluczowy kofaktor dla inhibitora proteazy zależnego od białka Z (ZPI), wygaszając kaskadę krzepnięcia (hamuje czynnik Xa). W mózgu wykazuje bezpośrednie działanie neuroprotekcyjne: chroni śródbłonek BBB oraz neurony przed apoptozą wywołaną niedotlenieniem lub lokalnym odczynem zakrzepowo-zapalnym.", heading: "rs4253243", genotype: "T/T", tone: "positive" }] } } },
  PTEN: { headline: "C/C — Homozygota alleliczna C", impact: "Typowy profil populacyjny tag-SNP rs701848. Nie oznacza Zespołu Cowdena ani mutacji LoF — te wymagają osobnej analizy sekwencji/CNV.", toneCtx: { heading: "rs701848", genotype: "C/C", tone: "neutral" }, variants: [{ headline: "C/C — Homozygota alleliczna C", text: "Typowy profil populacyjny tag-SNP rs701848. Nie oznacza Zespołu Cowdena ani mutacji LoF — te wymagają osobnej analizy sekwencji/CNV.", heading: "rs701848", genotype: "C/C", tone: "neutral" }], byTopic: { asd: { variants: [{ headline: "C/C — Homozygota alleliczna C", text: "Rola biologiczna genu/białka: PTEN to enzym działający jako jeden z najważniejszych supresorów nowotworowych w organizmie. Jest bezpośrednim negatywnym regulatorem szlaku PI3K/Akt/mTOR. Hamuje nadmierną proliferację, przerost somatyczny neuronów oraz patologiczne zagęszczenie wypustek synaptycznych.", heading: "rs701848", genotype: "C/C", tone: "neutral" }] } } },
