  QTRT1: { headline: "G/G — Maksymalna integracja mikroskładnika", impact: "Wydajne wykorzystanie queuine dostarczanej przez mikrobiotę. Optymalna dynamika translacji i stabilna synteza transporterów monoamin.", toneCtx: { heading: "rs2290432", genotype: "G/G", tone: "positive" }, variants: [{ headline: "G/G — Maksymalna integracja mikroskładnika", text: "Wydajne wykorzystanie queuine dostarczanej przez mikrobiotę. Optymalna dynamika translacji i stabilna synteza transporterów monoamin.", heading: "rs2290432", genotype: "G/G", tone: "positive" }], byTopic: { dopamine: { variants: [{ headline: "G/G — Maksymalna integracja mikroskładnika", text: "Rola biologiczna genu/białka: Enzym ten podmienia guaninę w pozycji 34 (antykodon) wybranych tRNA na unikalną zasadę azotową – queuine (pochodzącą wyłącznie z diety i mikrobiomu jelitowego). Modyfikacja ta optymalizuje prędkość translacji oraz precyzyjnie reguluje ekspresję genów odpowiedzialnych za homeostazę neurotransmiterów monoaminowych (dopamina, serotonina).", heading: "rs2290432", genotype: "G/G", tone: "positive" }] }, serotonin: { variants: [{ headline: "G/G — Maksymalna integracja mikroskładnika", text: "Rola biologiczna genu/białka: Enzym ten podmienia guaninę w pozycji 34 (antykodon) wybranych tRNA na unikalną zasadę azotową – queuine (pochodzącą wyłącznie z diety i mikrobiomu jelitowego). Modyfikacja ta optymalizuje prędkość translacji oraz precyzyjnie reguluje ekspresję genów odpowiedzialnych za homeostazę neurotransmiterów monoaminowych (dopamina, serotonina).", heading: "rs2290432", genotype: "G/G", tone: "positive" }] }, sport: { variants: [{ headline: "G/G — Maksymalna integracja mikroskładnika", text: "Wydajne wykorzystanie queuine dostarczanej przez mikrobiotę. Optymalna dynamika translacji i stabilna synteza transporterów monoamin.", heading: "rs2290432", genotype: "G/G", tone: "positive" }] } } },
  RET: { headline: "A/T — Skłonność do czynnościowych zaburzeń jelitowych (np.", impact: "IBS o typie zaparciowym) pod wpływem stresu psychofizycznego.", toneCtx: { heading: "rs1800858", genotype: "A/T", tone: "neutral" }, variants: [{ headline: "A/T — Skłonność do czynnościowych zaburzeń jelitowych (np.", text: "IBS o typie zaparciowym) pod wpływem stresu psychofizycznego.", heading: "rs1800858", genotype: "A/T", tone: "neutral" }], byTopic: { dopamine: { variants: [{ headline: "A/T — Skłonność do czynnościowych zaburzeń jelitowych (np.", text: "Rola biologiczna genu/białka: Koduje receptorową kinazę tyrozynową dla ligandów z rodziny GDNF (glejowych czynników neurotroficznych). RET jest absolutnie krytyczny dla migracji i różnicowania komórek grzebienia nerwowego, które formują Autonomiczny (Jelitowy) Układ Nerwowy (ENS) oraz jądra dopaminergiczne w śródmózgowiu.", heading: "rs1800858", genotype: "A/T", tone: "neutral" }] } } },
  RIMS1: { headline: "T/T — Homozygota alleliczna T", impact: "Typowy profil populacyjny tag-SNP rs11064560. Nie oznacza mutacji LoF ani klinicznego ryzyka schizofrenii — rzadkie LoF wymagają sekwencjonowania.", toneCtx: { heading: "rs11064560", genotype: "T/T", tone: "neutral" }, variants: [{ headline: "T/T — Homozygota alleliczna T", text: "Typowy profil populacyjny tag-SNP rs11064560. Nie oznacza mutacji LoF ani klinicznego ryzyka schizofrenii — rzadkie LoF wymagają sekwencjonowania.", heading: "rs11064560", genotype: "T/T", tone: "neutral" }], byTopic: { asd: { variants: [{ headline: "T/T — Homozygota alleliczna T", text: "Rola biologiczna genu/białka: Koduje białko RIM1 – kluczowy komponent strefy aktywnej synapsy presynaptycznej. RIM1 fizycznie koordynuje dokowanie, priming (\"uzbrajanie\") oraz fuzję pęcherzyków synaptycznych z błoną komórkową w bezpośredniej odpowiedzi na napływ jonów wapnia przez kanały napięciowe. Decyduje o sile, tempie i precyzji sygnału nerwowego.", heading: "rs11064560", genotype: "T/T", tone: "neutral" }] }, scz: { variants: [{ headline: "T/T — Homozygota alleliczna T", text: "Typowy profil populacyjny tag-SNP rs11064560. Nie oznacza mutacji LoF ani klinicznego ryzyka schizofrenii — rzadkie LoF wymagają sekwencjonowania.", heading: "rs11064560", genotype: "T/T", tone: "neutral" }] } } },
