  SLC12A5: { headline: "A/G — Suboptymalna ekspresja", impact: "Lekkie osłabienie potencjału hamującego GABA. Objawia się gorszą tolerancją na stres sensoryczny i podatnością na stany lękowe przy zmęczeniu.", toneCtx: { heading: "rs2885267", genotype: "A/G", tone: "neutral" }, variants: [{ headline: "A/G — Suboptymalna ekspresja", text: "Lekkie osłabienie potencjału hamującego GABA. Objawia się gorszą tolerancją na stres sensoryczny i podatnością na stany lękowe przy zmęczeniu.", heading: "rs2885267", genotype: "A/G", tone: "neutral" }], byTopic: { asd: { variants: [{ headline: "A/G — Suboptymalna ekspresja", text: "Rola biologiczna genu/białka: Koduje transporter KCC2, który wypompowuje jony chlorkowe ($Cl^-$) z wnętrza neuronu na zewnątrz. Jest to absolutnie fundamentalne: wysoka aktywność KCC2 w dojrzałym mózgu sprawia, że otwarcie kanału GABA-A powoduje napływ $Cl^-$ do środka i hiperpolaryzację (hamowanie neuronu). W niedojrzałym mózgu lub przy dysfunkcji KCC2, GABA działa paradoksalnie – pobudzająco!", heading: "rs2885267", genotype: "A/G", tone: "neutral" }] }, mdd: { variants: [{ headline: "A/G — Suboptymalna ekspresja", text: "Lekkie osłabienie potencjału hamującego GABA. Objawia się gorszą tolerancją na stres sensoryczny i podatnością na stany lękowe przy zmęczeniu.", heading: "rs2885267", genotype: "A/G", tone: "neutral" }] }, sport: { variants: [{ headline: "A/G — Suboptymalna ekspresja", text: "Rola biologiczna genu/białka: Koduje transporter KCC2, który wypompowuje jony chlorkowe ($Cl^-$) z wnętrza neuronu na zewnątrz. Jest to absolutnie fundamentalne: wysoka aktywność KCC2 w dojrzałym mózgu sprawia, że otwarcie kanału GABA-A powoduje napływ $Cl^-$ do środka i hiperpolaryzację (hamowanie neuronu). W niedojrzałym mózgu lub przy dysfunkcji KCC2, GABA działa paradoksalnie – pobudzająco!", heading: "rs2885267", genotype: "A/G", tone: "neutral" }] } } },
