  TDO2: { headline: "T/T — Odporność na stresowy drenaż", impact: "Enzym wykazuje słabą reaktywność na kortyzol. Nawet przy chronicznym stresie pula tryptofanu pozostaje nienaruszona, zabezpieczając ciągłość syntezy neurotransmiterów. Wysoka rezyliencja psychiczna pod presją.", toneCtx: { heading: "rs1010816", genotype: "T/T", tone: "positive" }, variants: [{ headline: "T/T — Odporność na stresowy drenaż", text: "Enzym wykazuje słabą reaktywność na kortyzol. Nawet przy chronicznym stresie pula tryptofanu pozostaje nienaruszona, zabezpieczając ciągłość syntezy neurotransmiterów. Wysoka rezyliencja psychiczna pod presją.", heading: "rs1010816", genotype: "T/T", tone: "positive" }], byTopic: { neurodev: { variants: [{ headline: "T/T — Odporność na stresowy drenaż", text: "Rola biologiczna genu/białka: TDO2 to drugi (obok IDO1) nadrzędny enzym inicjujący szlak kynureninowy. Kluczowa różnica polega na regulacji: podczas gdy IDO1 jest aktywowany przez cytokiny zapalne, TDO2 reaguje bezpośrednio na glukokortykoidy (kortyzol). Odpowiada za masową degradację systemowego tryptofanu pod wpływem przewlekłego, psychologicznego stresu, uniemożliwiając jego wykorzystanie do produkcji serotoniny i…", heading: "rs1010816", genotype: "T/T", tone: "positive" }] }, serotonin: { variants: [{ headline: "T/T — Odporność na stresowy drenaż", text: "Enzym wykazuje słabą reaktywność na kortyzol. Nawet przy chronicznym stresie pula tryptofanu pozostaje nienaruszona, zabezpieczając ciągłość syntezy neurotransmiterów. Wysoka rezyliencja psychiczna pod presją.", heading: "rs1010816", genotype: "T/T", tone: "positive" }] } } },
